"""OrderPad: daily supplier order sheet for small restaurants.
Track par levels, count on-hand stock, generate supplier order texts."""
import json, sys, os
from datetime import date

DATA = "orderpad_data.json"

def load():
    if os.path.exists(DATA):
        with open(DATA) as f:
            return json.load(f)
    return {"items": {}, "orders": []}

def save(d):
    with open(DATA, "w") as f:
        json.dump(d, f, indent=2)

def set_item(d, name, supplier, par, unit):
